// Parse Tavily web search results into the Elevate AI job shape
// and compute a keyword-based match score.

const userContext = $('Get User Context').first().json;
const tavilyData = $input.first().json;

const userSkills = (userContext.skills || []).map(s => s.toLowerCase());
const userRole = (userContext.targetRole || '').toLowerCase();
const gaps = (userContext.careerPlanGaps || []).map(s => s.toLowerCase());

function extractCompany(title, url) {
  // Try "Role at Company" pattern
  const atMatch = title.match(/(?:\bat\b|@)\s+([A-Z][A-Za-z0-9\s&.,'-]+?)(?:\s*[-|–•|]|\s+in\s|\s*$)/);
  if (atMatch) return atMatch[1].trim().slice(0, 60);

  // Try subdomain of known job boards (e.g. jobs.lever.co/company → company)
  try {
    const urlObj = new URL(url);
    const parts = urlObj.pathname.split('/').filter(Boolean);
    if (['lever', 'greenhouse', 'wellfound'].some(b => urlObj.hostname.includes(b))) {
      if (parts[0]) return parts[0].charAt(0).toUpperCase() + parts[0].slice(1);
    }
  } catch {}

  return 'Unknown';
}

function extractTitle(rawTitle) {
  // Strip trailing "at Company | Location" fragments
  return rawTitle
    .replace(/\s*[|–-].*$/, '')
    .replace(/\s+at\s+.+$/i, '')
    .replace(/\s+in\s+.+$/i, '')
    .trim() || rawTitle;
}

function extractLocation(content) {
  const m = content.match(/(?:location|based in|office in)[:\s]+([A-Za-z ,]+?)(?:\.|\n|$)/i);
  return m ? m[1].trim().slice(0, 60) : null;
}

function extractSalary(content) {
  const m = content.match(/\$[\d,]+k?\s*[-–]\s*\$[\d,]+k?|\$[\d,]+k?\s*(?:\/yr|\/year|per year|annually)/i);
  return m ? m[0] : null;
}

function isRemote(title, content) {
  return /\bremote\b|\banywhere\b|\bwfh\b|work from home/i.test(title + ' ' + content);
}

const results = tavilyData.results || [];

const jobs = results.map(result => {
  const title = result.title || '';
  const content = result.content || result.snippet || '';
  const url = result.url || '';
  const combined = (title + ' ' + content).toLowerCase();

  // Match score: role keywords + skill hits + gap hits + Tavily relevance score
  let score = Math.round((result.score || 0) * 30); // Tavily gives 0-1 relevance
  if (combined.includes(userRole)) score += 35;
  for (const skill of userSkills) {
    if (combined.includes(skill)) score += Math.min(5, 25); // cap skill contribution
  }
  for (const gap of gaps) {
    if (combined.includes(gap)) score += 3;
  }
  score = Math.min(score, 100);

  return {
    company: extractCompany(title, url),
    role: extractTitle(title),
    jobUrl: url,
    description: content.slice(0, 500),
    location: extractLocation(content),
    salaryRange: extractSalary(content),
    remote: isRemote(title, content),
    matchScore: score,
  };
});

// Only forward jobs with a meaningful score and a valid URL
const filtered = jobs.filter(j => j.matchScore >= 15 && j.jobUrl && j.role && j.role.length > 3);

return [{ json: { jobs: filtered } }];
